import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
} from '@angular/core';
import { MatIconModule } from '@angular/material/icon';

import { SatTag } from '../tag';
import { satStatusTagIcon } from '../types/tag-status-icon';
import { SatTagStatus } from '../types/tag-status-type';

/**
 * The `SatStatusTag` is used to display status labels with predefined styles and icons.
 * It supports various statuses like success, warning, info, etc., and automatically applies the appropriate styles and icons based on different status types mentioned in `SatTagStatus`, and the icon or the style of this component is predefined for the selected status.
 * You can also provide a custom icon to overwrite the predefined icon for a specific status.
 *
 * @example
 * <sat-status-tag status="success"> Success </sat-status-tag>
 */
@Component({
  selector: 'sat-status-tag',
  imports: [SatTag, MatIconModule],
  template: `
    <sat-tag
      [style.backgroundColor]="backgroundColor()"
      [style.color]="color()"
      [class.sat-status-tag-neutral-quiet]="status() === 'neutral-quiet'"
    >
      <div class="sat-tag-icon">
        @if (!(hideIcon() || satHideIcon())) {
          <ng-container #statusTagIconContainer>
            <ng-content select="[mat-icon], mat-icon"></ng-content>
          </ng-container>
          @if (statusTagIconContainer?.previousElementSibling?.localName !== 'mat-icon') {
            <mat-icon aria-hidden="true" [svgIcon]="defaultIcon()"></mat-icon>
          }
        }
      </div>
      <ng-content></ng-content>
    </sat-tag>
  `,
  styles: `
    :host {
      display: inline-flex;
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SatStatusTag {
  /**
   * The status of the tag, which determines its appearance and color.
   * This should be one of the predefined statuses.
   * @type {SatTagStatus}
   * @required
   */
  readonly status = input.required<SatTagStatus>();

  /**
   * Whether to hide the icon in the tag.
   * @deprecated Use `hideIcon` instead.
   */
  readonly satHideIcon = input<boolean, boolean>(false, { transform: booleanAttribute });

  /**
   * Whether to hide the icon in the tag.
   */
  readonly hideIcon = input<boolean, boolean>(false, { transform: booleanAttribute });

  readonly backgroundColor = computed(() => `var(--sat-tag-${this.status()}-container)`);

  readonly color = computed(() => `var(--sat-tag-on-${this.status()}-container)`);

  readonly defaultIcon = computed(
    () => satStatusTagIcon[this.status()] || satStatusTagIcon.neutral,
  );
}
