import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';
import { MatIconModule } from '@angular/material/icon';

import { SatTag } from '../tag';
import { SatTagCategory } from '../types/tag-category-type';

/**
 * The `SatCategoryTag` is used to display category labels with predefined styles.
 * It supports various categories like purple, blue, pink, etc., and automatically applies the appropriate styles based on the category type mentioned in `SatTagCategory`.
 * There is no default icon for the category component. You need to provide a custom icon which meets your requirements. Otherwise no icon will be displayed.
 *
 * @example
 * <sat-category-tag category="purple">
 *   <mat-icon aria-label="custom icon" svgIcon="tag"></mat-icon>
 *   Purple Category
 * </sat-category-tag>
 */
@Component({
  selector: 'sat-category-tag',
  imports: [SatTag, MatIconModule],
  template: `
    <sat-tag
      [style.backgroundColor]="backgroundColor()"
      [style.color]="color()"
    >
      <div class="sat-tag-icon">
        <ng-content select="[mat-icon], mat-icon"></ng-content>
      </div>
      <ng-content></ng-content>
    </sat-tag>
  `,
  styles: `
    :host {
      display: inline-flex;
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SatCategoryTag {
  /**
   * The category of the tag, which determines its style and icon.
   * This should be one of the predefined categories.
   *
   * @type {SatTagCategory}
   * @required
   */
  readonly category = input.required<SatTagCategory>();

  /** @ignore */
  readonly backgroundColor = computed(() => `var(--sat-tag-cat-${this.category()}-container)`);

  /** @ignore */
  readonly color = computed(() => `var(--sat-tag-on-cat-${this.category()}-container)`);
}
